export const threadFor = (id) =>
  threads.find((t) => t.ids.includes(id)) || threads.find((t) => t.bridges.includes(id));
export function connectedIds(id) {
  const t = threadFor(id);
  return t ? [...new Set([...t.ids, ...t.bridges])].filter((x) => x !== id) : [];
}
